#!/bin/bash
echo "=== TRIEN KHAI CLIPROXYAPI KHONG CAN ROOT ==="
DIR="/var/lib/ocarun/cliproxyapi"
mkdir -p "$DIR/oauth"
cd "$DIR"

echo "[1] Downloading CLIProxyAPI binary Linux AMD64..."
if [ ! -f "cli-proxy-api" ]; then
    curl -sSL "https://github.com/router-for-me/CLIProxyAPI/releases/download/v8.0.47/CLIProxyAPI_8.0.47_linux_amd64.tar.gz" -o cpa.tar.gz
    tar -xzf cpa.tar.gz
    rm -f cpa.tar.gz
    chmod +x cli-proxy-api
fi

echo "[2] Writing config.yaml..."
cat << 'CONFIG_EOF' > "$DIR/config.yaml"
config-version: 8
server:
  host: ""
  port: 8317
management:
  allow-remote: true
  secret-key: "123456"
oauth:
  auth-dir: "/var/lib/ocarun/cliproxyapi/oauth"
auth-dir: "/var/lib/ocarun/cliproxyapi/oauth"
access:
  api-keys:
    - "123456"
CONFIG_EOF

echo "[3] Writing 4 OAuth accounts..."
echo '' | base64 -d > "$DIR/oauth/antigravity-ananhs123@gmail.com.json"
echo '' | base64 -d > "$DIR/oauth/antigravity-nckhvakhoinghiep@gmail.com.json"
echo '' | base64 -d > "$DIR/oauth/antigravity-vanthang2006xyz@gmail.com.json"
echo '' | base64 -d > "$DIR/oauth/codex-6898ef2d-bufordfelix368+jyflpjh0@gmail.com-plus.json"

echo "[4] Killing any old process..."
pkill -f "cli-proxy-api" 2>/dev/null || true
sleep 1

echo "[5] Creating start.sh launcher..."
cat << 'START_EOF' > "$DIR/start.sh"
#!/bin/bash
DIR="/var/lib/ocarun/cliproxyapi"
cd "$DIR"
nohup "$DIR/cli-proxy-api" --config "$DIR/config.yaml" </dev/null >"$DIR/cpa.log" 2>&1 &
START_EOF
chmod +x "$DIR/start.sh"

echo "[6] Starting CLIProxyAPI background daemon..."
nohup "$DIR/cli-proxy-api" --config "$DIR/config.yaml" </dev/null >"$DIR/cpa.log" 2>&1 &
PID=$!
sleep 3

if ps -p $PID > /dev/null 2>&1; then
    echo "SUCCESS: CLIProxyAPI is running with PID: $PID"
else
    echo "Failed to start. Log content:"
    cat "$DIR/cpa.log"
fi

echo "[7] Local endpoint test..."
curl -s http://127.0.0.1:8317/v1/models | head -c 300
echo ""

echo "[8] Setting up @reboot cron..."
(crontab -l 2>/dev/null | grep -v "cliproxyapi"; echo "@reboot /bin/bash /var/lib/ocarun/cliproxyapi/start.sh") | crontab - 2>/dev/null || true

echo "=== CAI DAT HOAN TAT 100%! ==="
